#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basic() {
        assert_eq!(eval_rpn("3 4 + 2 *"), Ok(14));
        assert_eq!(eval_rpn("5 1 2 + 4 * + 3 -"), Ok(14));
        assert_eq!(eval_rpn("42"), Ok(42));
    }

    #[test]
    fn order_and_negatives() {
        assert_eq!(eval_rpn("10 3 -"), Ok(7));
        assert_eq!(eval_rpn("-7 2 /"), Ok(-3));
        assert_eq!(eval_rpn("  2   -3 * "), Ok(-6));
    }

    #[test]
    fn errors() {
        assert_eq!(eval_rpn("1 0 /"), Err(RpnError::DivisionByZero));
        assert_eq!(eval_rpn("1 +"), Err(RpnError::StackUnderflow));
        assert_eq!(eval_rpn("1 2 x"), Err(RpnError::InvalidToken("x".to_string())));
        assert_eq!(eval_rpn("1 2"), Err(RpnError::LeftoverOperands(2)));
        assert_eq!(eval_rpn(""), Err(RpnError::LeftoverOperands(0)));
    }

    #[test]
    fn overflow() {
        assert_eq!(eval_rpn("9223372036854775807 1 +"), Err(RpnError::Overflow));
        assert_eq!(eval_rpn("-9223372036854775808 -1 /"), Err(RpnError::Overflow));
        assert_eq!(eval_rpn("4611686018427387904 2 *"), Err(RpnError::Overflow));
    }
}
